@Composable
fun StatsScreen() {
    val context = LocalContext.current
    val coroutineScope = rememberCoroutineScope()

    val statsRepository = remember(context) {
        StatsRepositoryImpl(
            AppDatabase.getInstance(context).statDao(),
            AppDatabase.getInstance(context).statRecordDao()
        )
    }

    val healthConnectManager = remember(context) { HealthConnectManager(context) }
    var hasHealthConnectPermission by remember { mutableStateOf(false) }

    // List of stats from Room database
    val localStats by statsRepository.observeAllStats().collectAsState(initial = emptyList())

    // Popups/dialog states
    var selectedStatForDetails by remember { mutableStateOf<StatEntity?>(null) }
    var isManualLogOpen by remember { mutableStateOf<StatEntity?>(null) }

    val requestPermissionsLauncher = rememberLauncherForActivityResult(
        PermissionController.createPermissionRequestContract()
    ) { granted ->
        hasHealthConnectPermission = granted.containsAll(healthConnectManager.permissions)
        if (hasHealthConnectPermission) {
            Toast.makeText(context, "Health Connect підключено!", Toast.LENGTH_SHORT).show()
        } else {
            Toast.makeText(context, "Дозволи Health Connect відхилено", Toast.LENGTH_SHORT).show()
        }
    }

    // Seed initial stats definition if missing
    LaunchedEffect(Unit) {
        coroutineScope.launch {
            val existing = statsRepository.observeAllStats().firstOrNull() ?: emptyList()
            if (existing.isEmpty()) {
                statsRepository.insertStats(
                    listOf(
                        StatEntity("weight", "Маса", R.drawable.statweight, 0f),
                        StatEntity("pulse", "Пульс", R.drawable.statpulse, 0f),
                        StatEntity("steps", "Кількість кроків", R.drawable.statstepsamount, 0f),
                        StatEntity("sleep", "Сон", R.drawable.statsleeptime, 0f),
                        StatEntity("oxygen", "Рівень кисню", R.drawable.statoxygenlevel, 0f)
                    )
                )
            }

            // Check permissions
            hasHealthConnectPermission = healthConnectManager.hasAllPermissions()
        }
    }

    // Background sync from Health Connect if permissions are granted
    LaunchedEffect(hasHealthConnectPermission) {
        if (hasHealthConnectPermission) {
            coroutineScope.launch {
                try {
                    val stepsVal = healthConnectManager.getTodaySteps().toFloat()
                    val pulseVal = healthConnectManager.getLastHeartRate().toFloat()
                    val sleepVal = healthConnectManager.getLastSleepDurationHours()
                    val oxygenVal = healthConnectManager.getLastOxygen() * 100f // to percentage
                    val weightVal = healthConnectManager.getLastWeight()

                    val listToUpdate = listOf(
                        Triple("steps", "Кількість кроків", stepsVal),
                        Triple("pulse", "Пульс", pulseVal),
                        Triple("sleep", "Сон", sleepVal),
                        Triple("oxygen", "Рівень кисню", oxygenVal),
                        Triple("weight", "Маса", weightVal)
                    )

                    listToUpdate.forEach { (id, title, value) ->
                        if (value > 0f) {
                            val existing = statsRepository.observeStat(id).firstOrNull()
                            if (existing != null) {
                                statsRepository.updateStat(existing.copy(lastValue = value))
                                // Save a record today if none exists for today
                                val todayStart = Instant.now().truncatedTo(ChronoUnit.DAYS).toEpochMilli()
                                val todayEnd = Instant.now().toEpochMilli()
                                val records = statsRepository.observeRecordsInRange(id, todayStart, todayEnd).firstOrNull() ?: emptyList()
                                if (records.isEmpty()) {
                                    statsRepository.insertRecord(
                                        StatRecordEntity(
                                            statId = id,
                                            value = value,
                                            timestamp = System.currentTimeMillis()
                                        )
                                    )
                                }
                            }
                        }
                    }
                } catch (e: Exception) {
                    e.printStackTrace()
                }
            }
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(
                brush = Brush.verticalGradient(
                    colors = listOf(
                        Color(0xFF141C2B),
                        Color(0xFF120A1F),
                    )
                )
            ),
        contentAlignment = Alignment.Center
    ) {
        SoloLevelingBackground()

        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(top = 100.dp, start = 16.dp, end = 16.dp, bottom = 80.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            // Header with Health Connect Connection status
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 12.dp)
                    .background(
                        color = Color(0xFF1E283A).copy(alpha = 0.5f),
                        shape = RoundedCornerShape(12.dp)
                    )
                    .border(
                        width = 1.dp,
                        color = if (hasHealthConnectPermission) Color(0xFF00FF66).copy(alpha = 0.4f) else Color(0xFFFF3366).copy(alpha = 0.4f),
                        shape = RoundedCornerShape(12.dp)
                    )
                    .clickable {
                        if (!hasHealthConnectPermission) {
                            coroutineScope.launch {
                                requestPermissionsLauncher.launch(healthConnectManager.permissions)
                            }
                        }
                    }
                    .padding(horizontal = 16.dp, vertical = 12.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.SpaceBetween
            ) {
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        text = if (hasHealthConnectPermission) "HEALTH CONNECT ПІДКЛЮЧЕНО" else "ПІДКЛЮЧИТИ HEALTH CONNECT",
                        color = if (hasHealthConnectPermission) Color(0xFF00FF66) else Color(0xFFFF3366),
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Bold,
                        letterSpacing = 1.sp
                    )
                    Text(
                        text = if (hasHealthConnectPermission) "Синхронізація з Mi Fitness активна" else "Натисни для синхронізації з Mi Fitness / Band",
                        color = Color.Gray,
                        fontSize = 10.sp
                    )
                }

                Box(
                    modifier = Modifier
                        .size(10.dp)
                        .background(
                            color = if (hasHealthConnectPermission) Color(0xFF00FF66) else Color(0xFFFF3366),
                            shape = RoundedCornerShape(5.dp)
                        )
                )
            }

            Spacer(modifier = Modifier.height(10.dp))

            // Stat list grid
            LazyVerticalGrid(
                columns = GridCells.Fixed(2),
                modifier = Modifier.fillMaxSize(),
                horizontalArrangement = Arrangement.spacedBy(16.dp),
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                // Weight is highlighted at the top full-width, or just as standard item
                val weightStat = localStats.find { it.id == "weight" }
                val gridItems = localStats.filter { it.id != "weight" }

                weightStat?.let { stat ->
                    item(span = { androidx.compose.foundation.lazy.grid.GridItemSpan(2) }) {
                        StatCard(
                            stat = stat,
                            isFullWidth = true,
                            onClick = { selectedStatForDetails = stat },
                            onAddClick = { isManualLogOpen = stat }
                        )
                    }
                }

                items(gridItems) { stat ->
                    StatCard(
                        stat = stat,
                        isFullWidth = false,
                        onClick = { selectedStatForDetails = stat },
                        onAddClick = { isManualLogOpen = stat }
                    )
                }
            }
        }

        // Overlay Graphic dialog for stat details
        selectedStatForDetails?.let { stat ->
            StatDetailsDialog(
                stat = stat,
                healthConnectManager = healthConnectManager,
                hasHealthConnectPermission = hasHealthConnectPermission,
                statsRepository = statsRepository,
                onDismiss = { selectedStatForDetails = null }
            )
        }

        // Manual log entry dialog
        isManualLogOpen?.let { stat ->
            ManualLogDialog(
                stat = stat,
                statsRepository = statsRepository,
                onDismiss = { isManualLogOpen = null }
            )
        }
    }
}

@Composable
fun StatCard(
    stat: StatEntity,
    isFullWidth: Boolean,
    onClick: () -> Unit,
    onAddClick: () -> Unit
) {
    val neonColor = when (stat.id) {
        "weight" -> Color(0xFFFFB800)
        "pulse" -> Color(0xFFFF3366)
        "steps" -> Color(0xFF00FF66)
        "sleep" -> Color(0xFF00D2FF)
        "oxygen" -> Color(0xFFBD00FF)
        else -> Color(0xFF00E6F0)
    }

    val valueText = when (stat.id) {
        "weight" -> if (stat.lastValue > 0f) "%.1f кг".format(stat.lastValue) else "Ввести вагу"
        "pulse" -> if (stat.lastValue > 0f) "${stat.lastValue.toInt()} уд/хв" else "—"
        "steps" -> if (stat.lastValue > 0f) "${stat.lastValue.toInt()} кроків" else "0 кроків"
        "sleep" -> if (stat.lastValue > 0f) "%.1f год".format(stat.lastValue) else "—"
        "oxygen" -> if (stat.lastValue > 0f) "${stat.lastValue.toInt()}%" else "—"
        else -> "${stat.lastValue}"
    }

    Card(
        modifier = Modifier
            .fillMaxWidth()
            .height(if (isFullWidth) 120.dp else 150.dp)
            .clickable(
                onClick = onClick,
                interactionSource = remember { MutableInteractionSource() },
                indication = null
            ),
        shape = RoundedCornerShape(12.dp),
        colors = CardDefaults.cardColors(
            containerColor = Color(0xFF1E283A).copy(alpha = 0.5f)
        ),
        border = borderStroke(1.dp, neonColor.copy(alpha = 0.25f)),
        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
    ) {
        Box(modifier = Modifier.fillMaxSize()) {
            // "+" Button to add manual logs
            IconButton(
                onClick = { onAddClick() },
                modifier = Modifier
                    .align(Alignment.TopEnd)
                    .padding(4.dp)
                    .size(32.dp)
            ) {
                Icon(
                    imageVector = Icons.Default.Add,
                    contentDescription = "Ввести вручну",
                    tint = neonColor.copy(alpha = 0.8f),
                    modifier = Modifier.size(18.dp)
                )
            }

            if (isFullWidth) {
                Row(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(16.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Box(
                        modifier = Modifier.size(50.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        GlowIcon(stat.iconResId, stat.title, neonColor)
                    }

                    Spacer(modifier = Modifier.width(16.dp))

                    Column {
                        Text(
                            text = stat.title.uppercase(),
                            color = Color.Gray,
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Bold,
                            letterSpacing = 1.sp
                        )
                        Text(
                            text = valueText,
                            color = Color.White,
                            fontSize = 20.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }
                }
            } else {
                Column(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(12.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Center
                ) {
                    Box(
                        modifier = Modifier.size(44.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        GlowIcon(stat.iconResId, stat.title, neonColor)
                    }

                    Spacer(modifier = Modifier.height(10.dp))

                    Text(
                        text = stat.title,
                        color = Color.Gray,
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold,
                        textAlign = TextAlign.Center
                    )

                    Spacer(modifier = Modifier.height(4.dp))

                    Text(
                        text = valueText,
                        color = Color.White,
                        fontSize = 14.sp,
                        fontWeight = FontWeight.Bold,
                        textAlign = TextAlign.Center
                    )
                }
            }
        }
    }
}

@Composable
fun GlowIcon(resId: Int, contentDescription: String, color: Color) {
    Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            Icon(
                painter = painterResource(id = resId),
                contentDescription = null,
                tint = color,
                modifier = Modifier
                    .fillMaxSize()
                    .graphicsLayer {
                        renderEffect = RenderEffect
                            .createBlurEffect(12f, 12f, Shader.TileMode.DECAL)
                            .asComposeRenderEffect()
                    }
            )
        }
        Icon(
            painter = painterResource(id = resId),
            contentDescription = contentDescription,
            tint = color.copy(alpha = 0.9f),
            modifier = Modifier.fillMaxSize(0.9f)
        )
    }
}

@Composable
fun StatDetailsDialog(
    stat: StatEntity,
    healthConnectManager: HealthConnectManager,
    hasHealthConnectPermission: Boolean,
    statsRepository: StatsRepositoryImpl,
    onDismiss: () -> Unit
) {
    val coroutineScope = rememberCoroutineScope()
    var selectedTab by remember { mutableStateOf("Дн") } // "Дн", "Тиж", "Міс"
    var historyRecords by remember { mutableStateOf<List<StatRecordEntity>>(emptyList()) }

    val neonColor = when (stat.id) {
        "weight" -> Color(0xFFFFB800)
        "pulse" -> Color(0xFFFF3366)
        "steps" -> Color(0xFF00FF66)
        "sleep" -> Color(0xFF00D2FF)
        "oxygen" -> Color(0xFFBD00FF)
        else -> Color(0xFF00E6F0)
    }

    // Refresh history based on tab and permission status
    LaunchedEffect(selectedTab, hasHealthConnectPermission) {
        coroutineScope.launch {
            val days = when (selectedTab) {
                "Дн" -> 1
                "Тиж" -> 7
                "Міс" -> 30
                else -> 7
            }

            if (hasHealthConnectPermission) {
                try {
                    val start = Instant.now().minus(days.toLong(), ChronoUnit.DAYS)
                    val recordsList = mutableListOf<StatRecordEntity>()

                    when (stat.id) {
                        "steps" -> {
                            val hcRecords = healthConnectManager.getStepsHistory(start, Instant.now())
                            hcRecords.forEach { record ->
                                recordsList.add(StatRecordEntity(statId = "steps", value = record.count.toFloat(), timestamp = record.startTime.toEpochMilli()))
                            }
                        }
                        "pulse" -> {
                            val hcRecords = healthConnectManager.getHeartRateHistory(start, Instant.now())
                            hcRecords.forEach { record ->
                                val avgBpm = record.samples.map { it.beatsPerMinute }.average().toFloat()
                                if (avgBpm > 0) {
                                    recordsList.add(StatRecordEntity(statId = "pulse", value = avgBpm, timestamp = record.startTime.toEpochMilli()))
                                }
                            }
                        }
                        "oxygen" -> {
                            val hcRecords = healthConnectManager.getOxygenHistory(start, Instant.now())
                            hcRecords.forEach { record ->
                                recordsList.add(StatRecordEntity(statId = "oxygen", value = record.percentage.toFloat() * 100f, timestamp = record.time.toEpochMilli()))
                            }
                        }
                        "sleep" -> {
                            val hcRecords = healthConnectManager.getSleepHistory(start, Instant.now())
                            hcRecords.forEach { record ->
                                val hrs = (record.endTime.toEpochMilli() - record.startTime.toEpochMilli()).toFloat() / (1000 * 60 * 60)
                                recordsList.add(StatRecordEntity(statId = "sleep", value = hrs, timestamp = record.startTime.toEpochMilli()))
                            }
                        }
                        "weight" -> {
                            val hcRecords = healthConnectManager.getWeightHistory(start, Instant.now())
                            hcRecords.forEach { record ->
                                recordsList.add(StatRecordEntity(statId = "weight", value = record.weight.inKilograms.toFloat(), timestamp = record.time.toEpochMilli()))
                            }
                        }
                    }

                    if (recordsList.isNotEmpty()) {
                        historyRecords = recordsList.sortedBy { it.timestamp }
                        return@launch
                    }
                } catch (e: Exception) {
                    e.printStackTrace()
                }
            }

            // Fallback: Read local database records
            val startTime = Instant.now().minus(days.toLong(), ChronoUnit.DAYS).toEpochMilli()
            val localList = statsRepository.observeRecordsInRange(stat.id, startTime, System.currentTimeMillis()).firstOrNull() ?: emptyList()
            historyRecords = localList.sortedBy { it.timestamp }
        }
    }

    Dialog(
        onDismissRequest = onDismiss,
        properties = DialogProperties(usePlatformDefaultWidth = false)
    ) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(Color(0xFF0F1524).copy(alpha = 0.95f))
        ) {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(20.dp)
                    .verticalScroll(rememberScrollState())
            ) {
                // Header (Title & Close button)
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    IconButton(onClick = onDismiss) {
                        Icon(imageVector = Icons.Default.Close, contentDescription = "Закрити", tint = Color.White)
                    }

                    Text(
                        text = stat.title.uppercase(),
                        color = Color.White,
                        fontSize = 18.sp,
                        fontWeight = FontWeight.Bold,
                        letterSpacing = 1.sp
                    )

                    Spacer(modifier = Modifier.width(48.dp)) // Equal spacing
                }

                Spacer(modifier = Modifier.height(10.dp))

                // Date Label
                val dateFormat = SimpleDateFormat("dd MMMM yyyy р.", Locale("uk"))
                Text(
                    text = dateFormat.format(Date()),
                    color = Color.Gray,
                    fontSize = 12.sp,
                    modifier = Modifier.fillMaxWidth(),
                    textAlign = TextAlign.Center
                )

                Spacer(modifier = Modifier.height(20.dp))

                // Tab Selector (Day / Week / Month)
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(Color(0xFF1E283A).copy(alpha = 0.6f), RoundedCornerShape(20.dp))
                        .padding(4.dp),
                    horizontalArrangement = Arrangement.SpaceEvenly
                ) {
                    listOf("Дн", "Тиж", "Міс").forEach { tab ->
                        val isSelected = selectedTab == tab
                        Box(
                            modifier = Modifier
                                .weight(1f)
                                .height(36.dp)
                                .background(
                                    color = if (isSelected) Color(0xFF28364F) else Color.Transparent,
                                    shape = RoundedCornerShape(18.dp)
                                )
                                .clickable { selectedTab = tab },
                            contentAlignment = Alignment.Center
                        ) {
                            Text(
                                text = tab,
                                color = if (isSelected) Color.White else Color.Gray,
                                fontWeight = FontWeight.Bold,
                                fontSize = 13.sp
                            )
                        }
                    }
                }

                Spacer(modifier = Modifier.height(24.dp))

                // Primary Value Summary
                val lastValText = when (stat.id) {
                    "steps" -> "${historyRecords.sumOf { it.value.toInt() }} кроків"
                    "pulse" -> if (historyRecords.isNotEmpty()) "${historyRecords.map { it.value.toInt() }.average().toInt()} уд/хв" else "—"
                    "oxygen" -> if (stat.lastValue > 0f) "${stat.lastValue.toInt()}%" else "—"
                    "sleep" -> if (historyRecords.isNotEmpty()) "%.1f год".format(historyRecords.map { it.value }.average()) else "—"
                    "weight" -> if (stat.lastValue > 0f) "%.1f кг".format(stat.lastValue) else "—"
                    else -> "${stat.lastValue}"
                }

                Column(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    Text(
                        text = lastValText,
                        color = Color.White,
                        fontSize = 32.sp,
                        fontWeight = FontWeight.Bold
                    )
                    Text(
                        text = when (stat.id) {
                            "steps" -> "Всього за цей період"
                            "pulse" -> "Середній пульс"
                            "sleep" -> "Середній сон"
                            else -> "Останнє значення"
                        },
                        color = Color.Gray,
                        fontSize = 11.sp
                    )
                }

                Spacer(modifier = Modifier.height(24.dp))

                // Beautiful custom Canvas chart
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(200.dp),
                    shape = RoundedCornerShape(12.dp),
                    colors = CardDefaults.cardColors(containerColor = Color(0xFF1E283A).copy(alpha = 0.3f))
                ) {
                    Box(
                        modifier = Modifier
                            .fillMaxSize()
                            .padding(16.dp)
                    ) {
                        if (historyRecords.isEmpty()) {
                            Text(
                                text = "Немає даних за цей період",
                                color = Color.Gray,
                                modifier = Modifier.align(Alignment.Center),
                                fontSize = 12.sp
                            )
                        } else {
                            StatHistoryChart(records = historyRecords, neonColor = neonColor, statId = stat.id)
                        }
                    }
                }

                Spacer(modifier = Modifier.height(20.dp))

                // Metrics / summary grid
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp),
                    colors = CardDefaults.cardColors(containerColor = Color(0xFF1E283A).copy(alpha = 0.5f))
                ) {
                    Column(modifier = Modifier.padding(16.dp)) {
                        Text(
                            text = "ЩОДЕННИЙ ЗВІТ",
                            color = neonColor,
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold,
                            letterSpacing = 1.sp
                        )

                        Spacer(modifier = Modifier.height(12.dp))

                        // Render extra dynamic statistics metrics
                        when (stat.id) {
                            "steps" -> {
                                val totalSteps = historyRecords.sumOf { it.value.toInt() }
                                val distanceKm = totalSteps * 0.00075f
                                SummaryRow("Всього кроків", "$totalSteps")
                                SummaryRow("Відстань", "%.2f км".format(distanceKm))
                                SummaryRow("Середня к-сть кроків", "${if (historyRecords.isNotEmpty()) totalSteps / historyRecords.size else 0}")
                            }
                            "pulse" -> {
                                val values = historyRecords.map { it.value.toInt() }
                                SummaryRow("Діапазон пульсу", if (values.isNotEmpty()) "${values.minOrNull()} - ${values.maxOrNull()} уд/хв" else "—")
                                SummaryRow("Середній пульс", if (values.isNotEmpty()) "${values.average().toInt()} уд/хв" else "—")
                            }
                            "sleep" -> {
                                val values = historyRecords.map { it.value }
                                SummaryRow("Всього записів", "${values.size}")
                                SummaryRow("Середня тривалість", if (values.isNotEmpty()) "%.1f год".format(values.average()) else "—")
                            }
                            "oxygen" -> {
                                SummaryRow("Останній рівень кисню", if (stat.lastValue > 0f) "${stat.lastValue.toInt()}%" else "—")
                                SummaryRow("Нормальний діапазон", "95% - 100%")
                            }
                            "weight" -> {
                                val values = historyRecords.map { it.value }
                                SummaryRow("Поточна вага", if (stat.lastValue > 0f) "%.1f кг".format(stat.lastValue) else "—")
                                SummaryRow("Варіація за період", if (values.size > 1) "%.1f кг".format(values.last() - values.first()) else "0.0 кг")
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun SummaryRow(label: String, value: String) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 8.dp),
        horizontalArrangement = Arrangement.SpaceBetween
    ) {
        Text(text = label, color = Color.Gray, fontSize = 13.sp)
        Text(text = value, color = Color.White, fontSize = 13.sp, fontWeight = FontWeight.Bold)
    }
}

@Composable
fun StatHistoryChart(records: List<StatRecordEntity>, neonColor: Color, statId: String) {
    Canvas(modifier = Modifier.fillMaxSize()) {
        val maxVal = records.map { it.value }.maxOrNull()?.coerceAtLeast(10f) ?: 100f
        val pointsCount = records.size
        val width = size.width
        val height = size.height

        val stepX = if (pointsCount > 1) width / (pointsCount - 1) else width
        val heightMultiplier = height / maxVal

        if (statId == "steps" || statId == "sleep") {
            // Draw beautiful vertical bars like in Mi Fitness
            val barWidth = if (pointsCount > 1) (stepX * 0.6f).coerceIn(4f, 40f) else 30f
            records.forEachIndexed { i, record ->
                val x = if (pointsCount > 1) i * stepX else width / 2f
                val barHeight = record.value * heightMultiplier
                drawRect(
                    color = neonColor.copy(alpha = 0.8f),
                    topLeft = Offset(x - barWidth / 2, height - barHeight),
                    size = Size(barWidth, barHeight)
                )
                // glow blur effect simulation
                drawRect(
                    color = neonColor.copy(alpha = 0.15f),
                    topLeft = Offset(x - barWidth / 2 - 2, height - barHeight - 2),
                    size = Size(barWidth + 4, barHeight + 4)
                )
            }
        } else {
            // Draw continuous line graph for Pulse, Oxygen, and Weight
            val points = records.mapIndexed { i, record ->
                Offset(i * stepX, height - (record.value * heightMultiplier))
            }

            for (i in 0 until points.size - 1) {
                drawLine(
                    color = neonColor,
                    start = points[i],
                    end = points[i + 1],
                    strokeWidth = 3.dp.toPx()
                )
                // Draw glow behind line
                drawLine(
                    color = neonColor.copy(alpha = 0.2f),
                    start = points[i],
                    end = points[i + 1],
                    strokeWidth = 8.dp.toPx()
                )
            }

            // Draw endpoint circles
            points.forEach { pt ->
                drawCircle(
                    color = neonColor,
                    radius = 4.dp.toPx(),
                    center = pt
                )
            }
        }
    }
}

@Composable
fun ManualLogDialog(
    stat: StatEntity,
    statsRepository: StatsRepositoryImpl,
    onDismiss: () -> Unit
) {
    val coroutineScope = rememberCoroutineScope()
    var inputValue by remember { mutableStateOf("") }

    val neonColor = when (stat.id) {
        "weight" -> Color(0xFFFFB800)
        "pulse" -> Color(0xFFFF3366)
        "steps" -> Color(0xFF00FF66)
        "sleep" -> Color(0xFF00D2FF)
        "oxygen" -> Color(0xFFBD00FF)
        else -> Color(0xFF00E6F0)
    }

    val labelText = when (stat.id) {
        "weight" -> "Вага (кг)"
        "pulse" -> "Пульс (уд/хв)"
        "steps" -> "Кількість кроків"
        "sleep" -> "Тривалість сну (год)"
        "oxygen" -> "Рівень кисню (%)"
        else -> "Значення"
    }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = {
            Text(
                text = "НОВИЙ ЗАПИС: ${stat.title.uppercase()}",
                color = Color.White,
                fontSize = 14.sp,
                fontWeight = FontWeight.Bold
            )
        },
        text = {
            Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                Text(
                    text = "Введіть поточне значення для цього метричного показника:",
                    color = Color.Gray,
                    fontSize = 12.sp
                )

                OutlinedTextField(
                    value = inputValue,
                    onValueChange = { inputValue = it },
                    label = { Text(labelText) },
                    singleLine = true,
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                    modifier = Modifier.fillMaxWidth(),
                    colors = darkTextFieldColors()
                )
            }
        },
        confirmButton = {
            Button(
                onClick = {
                    val fVal = inputValue.toFloatOrNull()
                    if (fVal != null && fVal > 0f) {
                        coroutineScope.launch {
                            statsRepository.updateStat(stat.copy(lastValue = fVal))
                            statsRepository.insertRecord(
                                StatRecordEntity(
                                    statId = stat.id,
                                    value = fVal,
                                    timestamp = System.currentTimeMillis()
                                )
                            )
                            onDismiss()
                        }
                    } else {
                        onDismiss()
                    }
                },
                colors = ButtonDefaults.buttonColors(containerColor = neonColor.copy(alpha = 0.2f)),
                modifier = Modifier.border(1.dp, neonColor, RoundedCornerShape(8.dp))
            ) {
                Text("ЗБЕРЕГТИ", color = neonColor, fontWeight = FontWeight.Bold)
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) {
                Text("СКАСУВАТИ", color = Color(0xFFFF3366), fontWeight = FontWeight.Bold)
            }
        },
        containerColor = Color(0xFF1E283A),
        shape = RoundedCornerShape(12.dp)
    )
}

